import Foundation
import CoreGraphics
import QuartzCore
import ArcCore

public final class SmoothScrollEngine {
    public static let shared = SmoothScrollEngine()
    public static let magicEventTag: Int64 = 0x415243 // "ARC"

    private var displayTimer: Timer?
    private var velocityY: Double = 0
    private var velocityX: Double = 0
    private var isScrolling: Bool = false
    private var lastEventTime: TimeInterval = 0

    private let angleThresholdTan: Double = 0.36 // ~20 degrees deadzone

    private init() {}

    /// Check if event is generated by our own engine
    public static func isSyntheticEvent(_ event: CGEvent) -> Bool {
        return event.getIntegerValueField(.eventSourceUserData) == magicEventTag
    }

    /// Process incoming raw scroll event from CGEventTap
    /// Returns `true` if raw event should be suppressed from the default driver.
    public func handleScrollEvent(_ event: CGEvent) -> Bool {
        // 1. Extract deltas
        let intDy = event.getIntegerValueField(.scrollWheelEventDeltaAxis1)
        let intDx = event.getIntegerValueField(.scrollWheelEventDeltaAxis2)
        let fixedDy = event.getDoubleValueField(.scrollWheelEventFixedPtDeltaAxis1)
        let fixedDx = event.getDoubleValueField(.scrollWheelEventFixedPtDeltaAxis2)

        let rawDy = fixedDy != 0 ? fixedDy : (intDy != 0 ? Double(intDy) : event.getDoubleValueField(.scrollWheelEventDeltaAxis1))
        let rawDx = fixedDx != 0 ? fixedDx : (intDx != 0 ? Double(intDx) : event.getDoubleValueField(.scrollWheelEventDeltaAxis2))

        // 2. Check if horizontal side scroll is a gesture flick (Toggle Desktops)
        if GestureEngine.shared.handleHorizontalDelta(rawDx) {
            return true
        }

        // 3. Check if upward scroll is a gesture flick (Toggle Mission Control)
        if GestureEngine.shared.handleVerticalDelta(rawDy) {
            return true
        }

        let config = ArcConfig.shared

        // 4. Direction multiplier for Natural Scrolling:
        // By default on macOS, scrollWheel delta > 0 is scroll up (scrollbar moves up, content moves down).
        // Under Natural Scrolling, swiping finger forward/up should push content UP (scroll down -> delta < 0).
        let directionMultiplier = config.naturalScroll ? -1.0 : 1.0

        // If smooth scrolling is disabled, invert raw event in-place and let it pass through directly
        guard config.smoothScrollEnabled else {
            if config.naturalScroll {
                event.setIntegerValueField(.scrollWheelEventDeltaAxis1, value: -intDy)
                event.setIntegerValueField(.scrollWheelEventDeltaAxis2, value: -intDx)
                event.setDoubleValueField(.scrollWheelEventFixedPtDeltaAxis1, value: -fixedDy)
                event.setDoubleValueField(.scrollWheelEventFixedPtDeltaAxis2, value: -fixedDx)
                let pointDy = event.getIntegerValueField(.scrollWheelEventPointDeltaAxis1)
                let pointDx = event.getIntegerValueField(.scrollWheelEventPointDeltaAxis2)
                event.setIntegerValueField(.scrollWheelEventPointDeltaAxis1, value: -pointDy)
                event.setIntegerValueField(.scrollWheelEventPointDeltaAxis2, value: -pointDx)
                ArcEventMonitor.shared.recordVertical(delta: Double(-intDy))
            } else {
                ArcEventMonitor.shared.recordVertical(delta: Double(intDy))
            }
            return false // Let inverted event pass through directly to system WindowServer!
        }

        ArcEventMonitor.shared.recordVertical(delta: rawDy * directionMultiplier)

        let speedMultiplier = config.scrollSpeed * 8.0

        // Angle deadzone: if mostly vertical, ignore accidental horizontal drift
        var effectiveDx = rawDx
        if abs(rawDy) > 0.1 && abs(rawDx) / abs(rawDy) < angleThresholdTan {
            effectiveDx = 0
        }

        // Accumulate velocity
        velocityY += rawDy * directionMultiplier * speedMultiplier
        velocityX += effectiveDx * directionMultiplier * speedMultiplier

        lastEventTime = Date().timeIntervalSince1970

        if !isScrolling {
            isScrolling = true
            postScrollEvent(dy: 0, dx: 0, phase: .began)
            startDisplayTimer()
        }

        return true // Suppress raw event completely from default mouse driver!
    }

    private func startDisplayTimer() {
        displayTimer?.invalidate()
        // 120Hz display refresh: ~8.3ms
        displayTimer = Timer.scheduledTimer(withTimeInterval: 1.0 / 120.0, repeats: true) { [weak self] _ in
            self?.tick()
        }
    }

    private func tick() {
        let decay = ArcConfig.shared.momentumDecay
        let stepY = velocityY * 0.32
        let stepX = velocityX * 0.32

        velocityY *= decay
        velocityX *= decay

        let minVelocity = 0.15
        let hasRemainingVelocity = abs(velocityY) > minVelocity || abs(velocityX) > minVelocity

        if hasRemainingVelocity {
            postScrollEvent(dy: stepY, dx: stepX, phase: .changed)
        } else {
            displayTimer?.invalidate()
            displayTimer = nil
            isScrolling = false
            velocityY = 0
            velocityX = 0
            postScrollEvent(dy: 0, dx: 0, phase: .ended)
        }
    }

    private enum ScrollPhase {
        case began, changed, ended
    }

    private func postScrollEvent(dy: Double, dx: Double, phase: ScrollPhase) {
        guard let event = CGEvent(scrollWheelEvent2Source: nil,
                                  units: .pixel,
                                  wheelCount: 2,
                                  wheel1: Int32(dy),
                                  wheel2: Int32(dx),
                                  wheel3: 0) else {
            return
        }

        // Set subpixel float fields and magic source ID
        event.setDoubleValueField(.scrollWheelEventFixedPtDeltaAxis1, value: dy)
        event.setDoubleValueField(.scrollWheelEventFixedPtDeltaAxis2, value: dx)
        event.setIntegerValueField(.scrollWheelEventPointDeltaAxis1, value: Int64(dy))
        event.setIntegerValueField(.scrollWheelEventPointDeltaAxis2, value: Int64(dx))

        // Set line delta fallback for apps that do not consume pixel-continuous streams
        let lineY = Int64(dy / 8.0)
        let lineX = Int64(dx / 8.0)
        event.setIntegerValueField(.scrollWheelEventDeltaAxis1, value: lineY)
        event.setIntegerValueField(.scrollWheelEventDeltaAxis2, value: lineX)

        event.setIntegerValueField(.scrollWheelEventIsContinuous, value: 0)
        event.setIntegerValueField(.eventSourceUserData, value: SmoothScrollEngine.magicEventTag)

        let cgPhase: Int64
        switch phase {
        case .began: cgPhase = 1    // kCGScrollWheelEventScrollPhaseBegan
        case .changed: cgPhase = 2  // kCGScrollWheelEventScrollPhaseChanged
        case .ended: cgPhase = 4    // kCGScrollWheelEventScrollPhaseEnded
        }
        event.setIntegerValueField(.scrollWheelEventScrollPhase, value: cgPhase)

        event.post(tap: .cgSessionEventTap)
    }
}
